<section class="page-heading compact"><div class="container"><div class="eyebrow">YOUR SHORTLIST</div><h1>Your cart, <em>your call.</em></h1><p>Review your services and tell us where to deliver.</p></div></section><section class="section-pad"><div class="container"><div class="row g-5"><div class="col-lg-7"><h2 class="small-section-title">Selected services <span><?= count($items) ?></span></h2><?php if(!$items): ?><div class="empty-state"><div class="empty-icon">＋</div><h3>Your cart is waiting for an idea.</h3><p>Explore the catalogue and add a service to get started.</p><a class="btn btn-green" href="<?= e(url('services')) ?>">Browse services ↗</a></div><?php else: foreach($items as $item): ?><div class="cart-item"><div class="cart-item-art"><b><?= e(strtoupper(substr($item['name'],0,2))) ?></b></div><div class="cart-item-info"><small><?= e($item['vendor_name']) ?></small><h3><?= e($item['name']) ?></h3><p>Quantity: <?= (int)$item['quantity'] ?></p></div><strong><?= money($item['line_total']) ?></strong></div><?php endforeach; endif; ?></div><div class="col-lg-5"><div class="checkout-card"><h2>Delivery details</h2><p>Cash on Delivery is selected by default.</p><form method="post" action="<?= e(url('checkout')) ?>" enctype="multipart/form-data" class="form-stack"><?= csrf_field() ?><label>Delivery address<textarea class="form-control" name="delivery_address" rows="3" required placeholder="House, street, area, city"></textarea></label><label>Estimated delivery distance (km)<input class="form-control" type="number" name="distance_km" min="0" max="500" step="0.5" value="5" required><small class="field-help">Used for an initial estimate. A live routing API can replace this value.</small></label><label>Upload design (optional)<input class="form-control" type="file" name="design" accept=".pdf,.jpg,.jpeg,.png,.webp"><small class="field-help">PDF, JPG, PNG or WEBP · maximum 15 MB</small></label><div class="summary-row"><span>Items subtotal</span><strong><?= money($subtotal) ?></strong></div><div class="summary-row"><span>Delivery</span><span>Calculated per vendor</span></div><div class="summary-row summary-total"><span>Payment method</span><strong>Cash on Delivery</strong></div><button class="btn btn-green w-100" <?= !$items?'disabled':'' ?>>Place order ↗</button><small class="secure-note">Your order is split into vendor-specific fulfilment orders.</small></form></div></div></div></div></section>
